document.querySelectorAll('details').forEach(d=>d.open=true);
const root=document.querySelector('.notion-page-content')||document.body;
const imgs=[]; let lastHeading='';
const t=e=>(e.innerText||'').replace(/ /g,' ').trim();
const links=e=>[...e.querySelectorAll('a[href]')].map(a=>a.href).filter(h=>!h.startsWith('https://sonmiran9.oopy.io/#')&&!h.includes('lazyrockets'));
const isBlock=e=>typeof e.className==='string'&&/notion-[a-z_]+-block/.test(e.className);
function conv(node,depth){
  const out=[];
  for(const el of node.children){
    if(!isBlock(el)){out.push(...conv(el,depth));continue}
    const c=el.className;
    const ind='  '.repeat(depth);
    if(/notion-header-block/.test(c)){lastHeading=t(el);out.push('\n# '+lastHeading+'\n')}
    else if(/notion-sub_header-block/.test(c)){lastHeading=t(el);out.push('\n## '+lastHeading+'\n')}
    else if(/notion-sub_sub_header-block/.test(c)){lastHeading=t(el);out.push('\n### '+lastHeading+'\n')}
    else if(/notion-divider-block/.test(c)){out.push('\n---\n')}
    else if(/notion-code-block/.test(c)){
      const code=el.querySelector('pre,code,textarea');
      let body=code?t(code):t(el);
      let lang='';
      const lines=t(el).split('\n');
      if(lines.length&&/^[A-Za-z+#. ]{1,20}$/.test(lines[0])&&!body.startsWith(lines[0])) lang=lines[0].toLowerCase().replace(' ','');
      body=body.replace(/\n?(복사|Copy)\s*$/,'');
      out.push('\n```'+lang+'\n'+body+'\n```\n')
    }
    else if(/notion-image-block/.test(c)){
      const im=el.querySelector('img');
      if(im){const src=im.getAttribute('src')||im.src;const cap=t(el);imgs.push({i:imgs.length+1,src,caption:cap,heading:lastHeading});out.push('\n![IMG'+imgs.length+(cap?' '+cap:'')+'](IMG'+imgs.length+')\n')}
    }
    else if(/notion-(bulleted_list|numbered_list|to_do)-block/.test(c)){
      const own=[...el.children].find(ch=>!isBlock(ch));
      const kids=[...el.children].filter(ch=>isBlock(ch)||ch.querySelector('[class*="notion-"][class*="-block"]'));
      const mark=/numbered/.test(c)?'1. ':'- ';
      const text=own?t(own):t(el).split('\n')[0];
      out.push(ind+mark+text.replace(/\n/g,'\n'+ind+'  '));
      for(const k of kids){ if(isBlock(k)) out.push(...conv({children:[k]},depth+1)); else out.push(...conv(k,depth+1)); }
    }
    else if(/notion-callout-block/.test(c)){out.push('\n> '+t(el).replace(/\n/g,'\n> ')+'\n')}
    else if(/notion-quote-block/.test(c)){out.push('\n> '+t(el).replace(/\n/g,'\n> ')+'\n')}
    else if(/notion-table-block/.test(c)){
      const rows=[...el.querySelectorAll('tr')].map(r=>[...r.children].map(td=>t(td).replace(/\|/g,'\\|').replace(/\n/g,' ')));
      if(rows.length){out.push('');out.push('| '+rows[0].join(' | ')+' |');out.push('| '+rows[0].map(()=>'---').join(' | ')+' |');rows.slice(1).forEach(r=>out.push('| '+r.join(' | ')+' |'));out.push('')}
    }
    else if(/notion-(bookmark|embed|video|file|pdf)-block/.test(c)){const l=links(el);out.push('\n['+(t(el).split('\n')[0]||'link')+']('+(l[0]||'')+')\n')}
    else if(/notion-toggle-block/.test(c)){const own=[...el.children].find(ch=>!isBlock(ch));out.push(ind+'- ▸ '+(own?t(own).split('\n')[0]:t(el).split('\n')[0]));out.push(...conv(el,depth+1).filter(x=>x!==ind+'- ▸ '+t(el).split('\n')[0]))}
    else if(/notion-(column_list|column|page)-block/.test(c)){out.push(...conv(el,depth))}
    else if(/notion-text-block/.test(c)){const s=t(el);const l=links(el);out.push(s?ind+s.replace(/\n/g,'\n'+ind)+(l.length?'\n'+ind+l.map(u=>'  - 링크: '+u).join('\n'):''):'')}
    else {const s=t(el); if(s) out.push(ind+s)}
  }
  return out;
}
const md=conv(root,0).join('\n').replace(/\n{3,}/g,'\n\n');
({title:document.title,len:md.length,head:md.slice(0,3000),imgs})

