        time.sleep(0.2)
    result = nav.getResult()
    code = 0 if result == TaskResult.SUCCEEDED else 2
    log.info(f"RESULT {result.name} for {station} after {time.monotonic() - t0:.0f}s")
    args.destroy_node()
    rclpy.shutdown()
