bag=sys.argv[1]
r=SequentialReader(); r.open(StorageOptions(uri=bag,storage_id='mcap'),ConverterOptions('cdr','cdr'))
types={t.name:get_message(t.type) for t in r.get_all_topics_and_types()}
odom=[];m2o=[];amcl=[];plans=[];scans=[];cm=[];fp=[];cmd=[];cms=[]
while r.has_next():
    topic,data,t=r.read_next(); t=t*1e-9
    if topic not in types: continue
    m=deserialize_message(data,types[topic])
    if topic=='/tf':
        for tr in m.transforms:
            q=tr.transform.rotation; yaw=2*math.atan2(q.z,q.w)
            if tr.header.frame_id=='odom' and tr.child_frame_id=='base_link': odom.append((t,tr.transform.translation.x,tr.transform.translation.y,yaw))
            if tr.header.frame_id=='map' and tr.child_frame_id=='odom': m2o.append((t,tr.transform.translation.x,tr.transform.translation.y,yaw))
    elif topic=='/amcl_pose':
        p=m.pose.pose; q=p.orientation; amcl.append((t,p.position.x,p.position.y,2*math.atan2(q.z,q.w)))
    elif topic=='/plan': plans.append((t,[(p.pose.position.x,p.pose.position.y) for p in m.poses]))
    elif topic=='/scan': scans.append((t,m))
    elif topic=='/local_costmap/costmap': cm.append((t,m))
    elif topic=='/cmd_vel': cmd.append((t,m.linear.x,m.angular.z))
    elif topic=='/collision_monitor_state': cms.append((t,m.action_type,m.polygon_name))
print('odom',len(odom),'m2o',len(m2o),'amcl',len(amcl),'plans',len(plans),'scans',len(scans),'costmaps',len(cm),'cmd',len(cmd))
def pose_at(tq):
    o=min(odom,key=lambda a:abs(a[0]-tq)); mo=min(m2o,key=lambda a:abs(a[0]-tq)) if m2o else (0,0,0,0)
    c,s=math.cos(mo[3]),math.sin(mo[3]); return (mo[1]+c*o[1]-s*o[2], mo[2]+s*o[1]+c*o[2], mo[3]+o[3]), o
print('--- amcl pose samples'); 
for a in amcl[::max(1,len(amcl)//10)]: print(f' t={a[0]:.1f} ({a[1]:.2f},{a[2]:.2f},{math.degrees(a[3]):.0f})')
print('--- odom samples')
for o in odom[::max(1,len(odom)//12)]: print(f' t={o[0]:.1f} odom ({o[1]:.2f},{o[2]:.2f},{math.degrees(o[3]):.0f})')
print('--- cmd_vel nonzero span')
nz=[c for c in cmd if abs(c[1])>0.01 or abs(c[2])>0.01]
if nz: print(f' first {nz[0][0]:.1f} last {nz[-1][0]:.1f} n={len(nz)} vmin={min(c[1] for c in nz):.2f} vmax={max(c[1] for c in nz):.2f}')
print('--- plans')
for t,p in plans[:6]: print(f' t={t:.1f} n={len(p)} start=({p[0][0]:.2f},{p[0][1]:.2f}) end=({p[-1][0]:.2f},{p[-1][1]:.2f})', ' mid=',[(round(x,2),round(y,2)) for x,y in p[::max(1,len(p)//6)]])
print('--- collision monitor', cms[:6])
# scan near returns at a few times, in base_link (scan frame front_3d_lidar at base (-0.232,0,0.526))
print('--- near scan returns (<1.0 m from lidar), base_link frame, by time')
for t,m in scans[::max(1,len(scans)//8)]:
    rng=np.array(m.ranges); ang=m.angle_min+np.arange(len(rng))*m.angle_increment
    ok=np.isfinite(rng)&(rng<1.0)&(rng>0.05)
    x=rng[ok]*np.cos(ang[ok])-0.232; y=rng[ok]*np.sin(ang[ok])
    pts=sorted(zip(x.round(2),y.round(2)))
    print(f' t={t:.1f} n={ok.sum()} sample={pts[:12]}')
# local costmap lethal cells near robot at the last few costmaps
print('--- local costmap: lethal(>=99) cells within 1.2 m of base_link, in base frame')
for t,m in cm[::max(1,len(cm)//6)]:
    (bx,by,byaw),_=pose_at(t)
    g=np.array(m.data,dtype=np.int16).reshape(m.info.height,m.info.width)
    ys,xs=np.where(g>=99)
    wx=m.info.origin.position.x+(xs+0.5)*m.info.resolution; wy=m.info.origin.position.y+(ys+0.5)*m.info.resolution
    dx=wx-bx; dy=wy-by; c,s=math.cos(-byaw),math.sin(-byaw); lx=c*dx-s*dy; ly=s*dx+c*dy
    near=(np.hypot(lx,ly)<1.2)
    pts=sorted(set(zip(lx[near].round(1),ly[near].round(1))))
    print(f' t={t:.1f} robot map=({bx:.2f},{by:.2f},{math.degrees(byaw):.0f}) lethal_near={near.sum()} sample={pts[:16]}')
EOF
