    stall_check_s: float = 3.0        # 명령을 내는데 이만큼 움직임이 없으면 멈춘 것으로 본다
    stall_move_m: float = 0.02
    stall_turn_rad: float = 0.02      # 제자리 회전도 움직인 것으로 센다 (23차: 회전 구간이 멈춤으로 오판)
